#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/pre-commit/tasks/setup-precommit.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Install pre-commit hooks; --upgrade also updates them"
# MISE hide=true
# MISE tools={uv="latest", python="3.14", pre-commit="latest"}

# USAGE flag "--upgrade" help="also update the hook revisions"

import os
import shutil
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402


def run_precommit(*args):
  """Run pre-commit with args and return its exit code. The # MISE tools line
  gives pre-commit in every repository, so the task calls it directly. Without
  it, the code is 127, as the shell gives for a missing command."""
  precommit = shutil.which("pre-commit")
  if precommit is None:
    print("pre-commit: command not found", file=sys.stderr, flush=True)
    return 127
  return subprocess.run([precommit, *args], check=False).returncode


def main():
  helpers.print_header("Setting up pre-commit hooks ...")

  if os.environ.get("usage_upgrade", "false") == "true":
    helpers.print_subheader("Updating pre-commit hooks ...")
    code = run_precommit("autoupdate", "--config", ".config/pre-commit-config.yaml")
    if code != 0:
      return code

  helpers.print_subheader("Installing pre-commit ...")
  subprocess.run(["git", "config", "--local", "--unset-all", "core.hooksPath"], check=False)
  return run_precommit(
    "install", "--config", ".config/pre-commit-config.yaml", "--all", "--install-hooks", "--overwrite"
  )


if __name__ == "__main__":
  sys.exit(main())
